phase('Confirm')
const blockingList = [engine, td].filter(Boolean).flatMap(rv => [
  ...rv.reviews.flatMap(x => x.findings.filter(f => f.blocking).map(f => `${x.adr_id} ${f.id}: ${f.text}`)),
  ...rv.cross_adr.map(c => `${c.id} (owner ${c.owner_adr}): ${c.text} -> ${c.amendment}`),
])
const confirm = await agent(`Review-only: do NOT edit any file. Six Foundation ADRs were just revised in parallel:
${fileList}
Check two things and report: (1) for each blocking finding and cross-ADR item below, is it actually applied in the current file text (list unapplied ones in blocking_items_unapplied, with the ADR id); (2) residual inconsistencies BETWEEN the six ADRs and against ADR-0001/0002/0003/0007 and docs/registry/architecture.yaml as they now stand (interface names, ownership, dependency tables, layering, fault domains, who owns which lint). Read by section; be concrete with quotes.
Items to verify:
${blockingList.join('\n')}`,
  { label: 'confirm:cross-ADR', phase: 'Confirm', schema: CONFIRM_SCHEMA, model: 'sonnet', effort: 'high' })

phase('Registry')
const candidates = revised.map(r => ({ adr: r.adr_id, items: r.registry_candidates }))
const decisions = [
  ...authored.map(r => ({ adr: r.adr_id, stage: 'author', items: r.decisions })),
  ...revised.map(r => ({ adr: r.adr_id, stage: 'revise', items: r.decisions, applied: r.applied, declined: r.declined })),
]
