  severity: { type: 'string' }, text: { type: 'string' }, amendment: { type: 'string' } },
  required: ['id', 'adrs', 'owner_adr', 'severity', 'text', 'amendment'] } }
const REVIEW_SCHEMA = { type: 'object', properties: { adr_id: { type: 'string' }, verdict: { type: 'string' }, findings: FINDINGS, cross_adr: CROSS }, required: ['adr_id', 'verdict', 'findings', 'cross_adr'] }
const ADJ_SCHEMA = { type: 'object', properties: {
  rulings: { type: 'array', items: { type: 'object', properties: {
    id: { type: 'string' }, source_ids: { type: 'array', items: { type: 'string' } }, owner_adr: { type: 'string' },
    also_touch: { type: 'array', items: { type: 'string' } }, ruling: { type: 'string' }, amendment: { type: 'string' } },
    required: ['id', 'source_ids', 'owner_adr', 'also_touch', 'ruling', 'amendment'] } },
  notes: { type: 'string' } }, required: ['rulings', 'notes'] }
const REG = { type: 'array', items: { type: 'object', properties: {
  section: { type: 'string', enum: ['state_ownership', 'interfaces', 'performance_budgets', 'api_decisions', 'forbidden_patterns', 'referenced_by_update', 'revise_existing'] },
  name: { type: 'string' }, entry_yaml: { type: 'string' } }, required: ['section', 'name', 'entry_yaml'] } }
const REVISE_SCHEMA = { type: 'object', properties: {
  adr_id: { type: 'string' }, applied: { type: 'array', items: { type: 'string' } },
  declined: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, reason: { type: 'string' } }, required: ['id', 'reason'] } },
  registry_candidates: REG,
  gdd_sync: { type: 'array', items: { type: 'object', properties: { file: { type: 'string' }, old: { type: 'string' }, new: { type: 'string' } }, required: ['file', 'old', 'new'] } },
  decisions: { type: 'array', items: { type: 'object', properties: { point: { type: 'string' }, chosen: { type: 'string' }, reason: { type: 'string' } }, required: ['point', 'chosen', 'reason'] } },
  open_questions: { type: 'array', items: { type: 'string' } } },
  required: ['adr_id', 'applied', 'declined', 'registry_candidates', 'gdd_sync', 'decisions', 'open_questions'] }
const CONFIRM_SCHEMA = { type: 'object', properties: {
  residual: { type: 'array', items: { type: 'object', properties: { adrs: { type: 'array', items: { type: 'string' } }, severity: { type: 'string' }, text: { type: 'string' } }, required: ['adrs', 'severity', 'text'] } },
  unapplied: { type: 'array', items: { type: 'string' } }, notes: { type: 'string' } }, required: ['residual', 'unapplied', 'notes'] }

const FINISH = 'You MUST finish by calling the StructuredOutput tool with your result; a run that ends without it is lost. If any tool call is denied (for example a headless engine probe), do not stop: mark that claim UNVERIFIED and continue. Keep reads bounded (grep headings, then read ranges) so you do not run out of context.'

phase('Review')
const reviews = await pipeline(ADRS, a => parallel([
  () => agent(`Review-only: do NOT edit or write any file. Act as the project's godot-specialist (role definition: ${ROOT}/.claude/agents/godot-specialist.md). Validate ADR-${a.id} at ${a.path} (Proposed, Godot 4.7.2, GDScript) against the pinned engine reference ${ROOT}/docs/engine-reference/godot/ (VERSION.md, breaking-changes.md, deprecated-apis.md, current-best-practices.md, modules/). Report: (1) is the approach idiomatic for 4.7.2; (2) any API or pattern deprecated, changed post-cutoff, or wrong (signatures, things that will not compile: const of constructed objects, packed arrays passed by reference, 4.7 typed-return override rule, member names clashing with Object methods, typed-collection rules); (3) engine gotchas the draft misses. Check the ADR's own "probed 2026-10-28" claims for plausibility. Give a confidence per claim. Findings ids E1, E2... (blocking=true for wrong API / will not compile / incompatible), each with a concrete amendment. Engine contradictions with other ADRs (${ADRS.map(x => 'ADR-' + x.id).join(', ')}; existing ${EXISTING}) go in cross_adr with the owner_adr that should change. verdict: OK / NOTES / BLOCKING. ${FINISH}`,
    { label: `engine:ADR-${a.id}`, phase: 'Review', schema: REVIEW_SCHEMA, model: 'sonnet', effort: 'high' }),
  () => agent(`Review-only: do NOT edit or write any file. Act as the project's technical-director (role: ${ROOT}/.claude/agents/technical-director.md) and run gate TD-ADR (definition and verdict format: ${ROOT}/.claude/docs/director-gates/td-adr.md) on ADR-${a.id} at ${a.path} (Proposed, Godot 4.7.2, GDScript, review mode full). It was authored in parallel with five siblings that its author could not see:
${ALL_PATHS}
Existing Proposed ADRs: ${EXISTING}. Binding stances: ${ROOT}/docs/registry/architecture.yaml (the committed version). Architecture: ${ROOT}/docs/architecture/architecture.md (System Layer Map, Data Flow, API Boundaries, Required ADRs, Spikes, Open Questions). TR rows: grep "ADR-${a.id}" in docs/architecture/tr-baseline.md.
A first consistency pass already found these cross-ADR conflicts (file ${RUN1}, key "residuals"; read the ones naming ADR-${a.id}); confirm or refute each from the text and give your recommended owner and amendment in cross_adr, reusing the R-ids.
Check: contradictions with registry stances and ADR-0001/2/3/7; scope overlap or gaps vs the siblings; right-sizing for a solo/small-team MVP; traceability of its TR rows; honest spike gating; Depends On / Enables symmetry. verdict APPROVE / CONCERNS / REJECT; findings T1, T2... (blocking when it must change before Accept) with concrete amendments. Read only the sibling sections you need. ${FINISH}`,
    { label: `TD:ADR-${a.id}`, phase: 'Review', schema: REVIEW_SCHEMA, model: 'opus', effort: 'high' }),
]).then(([e, t]) => ({ id: a.id, path: a.path, engine: e, td: t })))

const ok = reviews.filter(Boolean)
const missing = []
ok.forEach(r => { if (!r.engine) missing.push(`engine:${r.id}`); if (!r.td) missing.push(`TD:${r.id}`) })
log(`Reviews back: ${ok.length * 2 - missing.length}/${ADRS.length * 2}${missing.length ? '; MISSING ' + missing.join(', ') : ''}`)

const verdictLine = r => `ADR-${r.id}: engine ${r.engine ? r.engine.verdict : 'MISSING'}, TD ${r.td ? r.td.verdict : 'MISSING'}`
const allCross = ok.flatMap(r => [...(r.engine ? r.engine.cross_adr : []), ...(r.td ? r.td.cross_adr : [])].map(c => ({ from: `ADR-${r.id}`, ...c })))

phase('Adjudicate')
const adj = await agent(`Act as the project's technical-director (${ROOT}/.claude/agents/technical-director.md). Six Foundation ADRs were authored in parallel and reviewed one by one; you are the single cross-ADR seat. Do NOT edit files. Produce one ruling per distinct conflict so each change has exactly one owner and no two revisers edit the same decision in opposite directions.
Inputs: (a) first-pass conflicts R1..R19 in ${RUN1} key "residuals"; (b) reviewers' cross-ADR items: ${JSON.stringify(allCross)}.
ADRs: ${ALL_PATHS}
Existing Proposed ADRs that may need amendment: ${EXISTING}. Owner may be ADR-0001, ADR-0002, ADR-0003 or ADR-0007 when the fix belongs there (e.g. kernel APIs the new ADRs request: deliver_frame_end, NotifyFacet, register_key_space, emit_event, new violation names, touch serial on the H1 allow-list, PRESENTATION_LATE, ControlHandle outcome shape). Merge duplicates (source_ids lists every R/E/T id covered). For each: owner_adr, also_touch (ADRs that must only align wording/references), the ruling (which side wins and why, in one or two sentences), and the exact amendment text or rule. Prefer the ADR whose scope owns the decision (architecture.md Required ADRs "Decides" column). Read ADR sections as needed with bounded reads. ${FINISH}`,
  { label: 'adjudicate:cross-ADR', phase: 'Adjudicate', schema: ADJ_SCHEMA, model: 'opus', effort: 'high' })
if (!adj) log('Adjudication FAILED — revisers get raw cross-ADR items only')

const fmt = (rv, tag) => !rv ? `${tag}: MISSING (review failed)` :
  `${tag} verdict ${rv.verdict}\n` + rv.findings.map(f => `${f.id} [${f.severity}${f.blocking ? ', BLOCKING' : ''}] ${f.text}\n  amendment: ${f.amendment}`).join('\n')
const rulingsFor = id => !adj ? allCross.filter(c => c.owner_adr.includes(id) || c.adrs.some(x => x.includes(id))) :
  adj.rulings.filter(r => r.owner_adr.includes(id) || r.also_touch.some(x => x.includes(id)))
const reviseTargets = [
  ...ok.map(r => ({ id: r.id, path: r.path, review: r })),
  ...args.amendable.filter(e => adj && adj.rulings.some(r => r.owner_adr.includes(e.id))).map(e => ({ id: e.id, path: e.path, review: null })),
]
log(`Revising ${reviseTargets.length} ADRs: ${reviseTargets.map(t => t.id).join(', ')}`)

phase('Revise')
const revised = (await parallel(reviseTargets.map(t => () => {
  const rul = rulingsFor(t.id)
  const own = rul.filter(r => (r.owner_adr || '').includes(t.id))
  const align = rul.filter(r => !(r.owner_adr || '').includes(t.id))
  return agent(`Revise ADR-${t.id} at ${t.path} (project ${ROOT}, Godot 4.7.2 GDScript; status stays Proposed; docs.density thorough). Autonomous mode: the action is "Revise flagged items". Read the file first; edit ONLY this file; never commit; do not edit the registry or GDDs.
${t.review ? `Apply every BLOCKING finding and every non-blocking one unless clearly wrong (then decline with a reason).\n\nENGINE REVIEW\n${fmt(t.review.engine, 'engine')}\n\nTD-ADR REVIEW\n${fmt(t.review.td, 'TD-ADR')}` : `This is an already-written Proposed ADR. You are ONLY applying the cross-ADR amendments below that the adjudicator assigned to it (requested by the new Foundation ADRs); change nothing else. Add a dated amendment note to its Review Log or a "## Amendments" section.`}

CROSS-ADR RULINGS YOU OWN (apply exactly; source ids in brackets):
${own.map(r => `${r.id} [${(r.source_ids || []).join(',')}] ${r.ruling}\n  amendment: ${r.amendment}`).join('\n') || 'none'}

CROSS-ADR RULINGS OWNED ELSEWHERE THAT YOUR TEXT MUST AGREE WITH (align references, names, Depends On / Enables, assumptions; do not take over the other ADR's decision):
${align.map(r => `${r.id} owner ${r.owner_adr}: ${r.ruling}\n  amendment: ${r.amendment}`).join('\n') || 'none'}

Update the Review Log (dated 2026-10-28) listing every finding/ruling id and what was done, replacing any "review unavailable" text with the real outcome. Remove Open Questions a ruling has answered. Previous registry candidates and GDD sync items for this ADR are in ${RUN1} (keys "registry_candidates" and "gdd_sync", entry "ADR-${t.id}" if present): return the FINAL set matching the revised text. For an existing registry entry whose signature or fields must change, use section "revise_existing" with the full replacement entry_yaml. ${FINISH}`,
    { label: `revise:ADR-${t.id}`, phase: 'Revise', schema: REVISE_SCHEMA, model: 'sonnet', effort: 'high' })
}))).filter(Boolean)
log(`Revised ${revised.length}/${reviseTargets.length}`)

phase('Confirm')
const confirm = await agent(`Review-only: do NOT edit files. After revision, check the Foundation ADR set for consistency:
${ALL_PATHS}
plus ${EXISTING}.
(1) For each ruling below, is it applied in the owner ADR and reflected in the also_touch ADRs? List any that are not in "unapplied" with the ruling id. (2) List residual inconsistencies that remain between any of these ADRs and the committed registry (interface names, ownership, dependency tables, layering, fault domains, lint ownership, frame model). Be concrete with quotes. ${FINISH}
Rulings: ${JSON.stringify(adj ? adj.rulings : allCross)}`,
  { label: 'confirm:cross-ADR', phase: 'Confirm', schema: CONFIRM_SCHEMA, model: 'sonnet', effort: 'high' })

phase('Registry')
const registryReport = await agent(`You are the single serial writer for docs/registry/architecture.yaml and production/session-logs/decision-log.md in ${ROOT}. Never commit; edit no other file.
(1) Registry: apply these final candidates from reviewed ADRs. Follow the file's header LAYOUT rules exactly. Read the file before each edit. New entries go after the last existing entry of their section, before that section's "# Example:" block. "referenced_by_update" adds the ADR path to the named existing entry's referenced_by (create the list if absent). "revise_existing" replaces the named entry's changed fields, sets revised: 2026-10-28, and keeps the old value in a YAML comment above the changed field (the file's rule). Merge duplicate names into one entry listing every ADR in referenced_by. Do not register a candidate whose stance the confirm step lists as still unresolved; report it as held instead. Then run  bash .claude/scripts/registry.sh validate  and  python -c "import yaml;yaml.safe_load(open('docs/registry/architecture.yaml',encoding='utf-8'))"  and fix any layout error you introduced. Preserve the file's existing line endings.
Candidates: ${JSON.stringify(revised.map(r => ({ adr: r.adr_id, items: r.registry_candidates })))}
Unresolved per confirm: ${JSON.stringify(confirm ? confirm.residual.filter(x => /major|blocking|high/i.test(x.severity)) : 'confirm unavailable')}
(2) Decision log: append (never rewrite) one section "## 2026-10-28 — architecture-decision review (foundation-adrs-review workflow)" covering: per ADR the engine and TD verdicts (${ok.map(verdictLine).join('; ')}), the "Revise flagged items" choice with applied and declined ids (${JSON.stringify(revised.map(r => ({ adr: r.adr_id, applied: r.applied, declined: r.declined, decisions: r.decisions })))}), the adjudicated cross-ADR rulings by id and owner, and the registry update. Format: **Decision point:** / **Options considered:** / **Chosen:** / **Reason:** / **Category:**.
Return a short plain-text report: entries added/revised per section, held candidates, validate output.`,
  { label: 'registry+log', phase: 'Registry', model: 'sonnet', effort: 'medium' })

return {
  verdicts: ok.map(r => ({ adr: r.id, engine: r.engine ? r.engine.verdict : null, engine_blocking: r.engine ? r.engine.findings.filter(f => f.blocking).length : null, td: r.td ? r.td.verdict : null, td_blocking: r.td ? r.td.findings.filter(f => f.blocking).length : null })),
  missing_reviews: missing,
  rulings: adj ? adj.rulings.map(r => ({ id: r.id, owner: r.owner_adr, ruling: r.ruling })) : null,
  revised: revised.map(r => ({ adr: r.adr_id, applied: r.applied.length, declined: r.declined, open_questions: r.open_questions })),
  gdd_sync: revised.map(r => ({ adr: r.adr_id, items: r.gdd_sync })),
  confirm,
  registryReport,
}
